/**
 * The Daily Grind — Field INP Monitoring & Attribution Engine
 *
 * Monitors Interaction to Next Paint (INP) in the field using:
 *  - Event Timing API (`event` and `first-input` entries)
 *  - Long Animation Frames API (`long-animation-frame` / LoAF entries)
 *  - Long Tasks API (`longtask` fallback)
 *
 * Attributes slow interactions to:
 *  1. Specific rendering & interaction phases:
 *     - Input Delay (`inputDelay`): `processingStart - startTime`
 *     - Processing Duration (`processingDuration`): `processingEnd - processingStart`
 *     - Presentation Delay (`presentationDelay`): `startTime + duration - processingEnd`
 *     - LoAF Rendering sub-phases: `workDuration`, `renderDuration`, `styleAndLayoutDuration`, `preLayoutDuration`
 *  2. Specific scripts causing the delay:
 *     - `sourceURL`, `sourceFunctionName`, `sourceCharPosition`, `invoker`, `invokerType`,
 *       `executionStart`, `duration`, `forcedStyleAndLayoutDuration`, `pauseDuration`
 */
(function initINPFieldMonitor() {
  'use strict';

  const CONFIG = {
    endpoint: window.INP_TELEMETRY_ENDPOINT || '/api/rum/inp',
    slowThresholdMs: 40,
    goodThresholdMs: 200,
    poorThresholdMs: 500,
    maxLoAFBuffer: 150,
    maxInteractionsTracked: 100
  };

  // Ring buffers and state
  const loafEntries = [];
  const longTaskEntries = [];
  const interactionsById = new Map();
  let interactionCount = 0;
  let lastReportedINPId = null;

  const state = {
    currentINP: null,
    interactions: [],
    loafBuffer: loafEntries,
    longTaskBuffer: longTaskEntries,
    beaconsSent: []
  };

  /**
   * Computes a concise, readable CSS selector for a DOM Element target.
   */
  function getTargetSelector(node) {
    if (!node || !(node instanceof Element)) return 'unknown';
    const parts = [];
    let el = node;
    while (el && el !== document.documentElement && parts.length < 4) {
      let selector = el.nodeName.toLowerCase();
      if (el.id) {
        selector += `#${el.id}`;
        parts.unshift(selector);
        break;
      }
      if (el.classList && el.classList.length > 0) {
        selector += '.' + Array.from(el.classList).slice(0, 2).join('.');
      }
      parts.unshift(selector);
      el = el.parentElement;
    }
    return parts.join(' > ') || 'document';
  }

  /**
   * Classifies INP value according to Core Web Vitals thresholds:
   * - good: <= 200ms
   * - needs-improvement: > 200ms and <= 500ms
   * - poor: > 500ms
   */
  function getINPRating(duration) {
    if (duration <= CONFIG.goodThresholdMs) return 'good';
    if (duration <= CONFIG.poorThresholdMs) return 'needs-improvement';
    return 'poor';
  }

  /**
   * Finds all Long Animation Frame (LoAF) entries overlapping an interaction's
   * time range [startTime, startTime + duration] and extracts detailed
   * rendering phase breakdowns and script attribution records.
   */
  function attributeWithLoAF(startTime, endTime) {
    const overlappingLoAFs = loafEntries.filter((loaf) => {
      const loafEnd = loaf.startTime + loaf.duration;
      return loaf.startTime <= endTime && loafEnd >= startTime;
    });

    const scripts = [];
    let totalWorkDuration = 0;
    let totalRenderDuration = 0;
    let totalPreLayoutDuration = 0;
    let totalStyleAndLayoutDuration = 0;
    let totalBlockingDuration = 0;

    for (const loaf of overlappingLoAFs) {
      const loafEnd = loaf.startTime + loaf.duration;
      const workDuration = loaf.renderStart
        ? Math.max(0, loaf.renderStart - loaf.startTime)
        : loaf.duration;
      const renderDuration = loaf.renderStart
        ? Math.max(0, loafEnd - loaf.renderStart)
        : 0;
      const preLayoutDuration =
        loaf.renderStart && loaf.styleAndLayoutStart
          ? Math.max(0, loaf.styleAndLayoutStart - loaf.renderStart)
          : 0;
      const styleAndLayoutDuration = loaf.styleAndLayoutStart
        ? Math.max(0, loafEnd - loaf.styleAndLayoutStart)
        : 0;

      totalWorkDuration += workDuration;
      totalRenderDuration += renderDuration;
      totalPreLayoutDuration += preLayoutDuration;
      totalStyleAndLayoutDuration += styleAndLayoutDuration;
      totalBlockingDuration += loaf.blockingDuration || 0;

      if (Array.isArray(loaf.scripts) || loaf.scripts) {
        for (const s of Array.from(loaf.scripts)) {
          scripts.push({
            invoker: s.invoker || 'unknown',
            invokerType: s.invokerType || 'unknown',
            sourceURL: s.sourceURL || document.location.href,
            sourceFunctionName: s.sourceFunctionName || '(anonymous)',
            sourceCharPosition:
              typeof s.sourceCharPosition === 'number' ? s.sourceCharPosition : -1,
            startTime: round(s.startTime),
            executionStart: round(s.executionStart),
            compileDuration: round(
              Math.max(0, (s.executionStart || s.startTime) - s.startTime)
            ),
            duration: round(s.duration),
            forcedStyleAndLayoutDuration: round(s.forcedStyleAndLayoutDuration || 0),
            pauseDuration: round(s.pauseDuration || 0),
            windowAttribution: s.windowAttribution || 'self'
          });
        }
      }
    }

    // Sort scripts descending by duration so the primary culprit script is first
    scripts.sort((a, b) => b.duration - a.duration);

    // Fallback to Long Tasks API if LoAF did not capture any overlapping frames
    const overlappingLongTasks = longTaskEntries
      .filter((lt) => {
        const ltEnd = lt.startTime + lt.duration;
        return lt.startTime <= endTime && ltEnd >= startTime;
      })
      .map((lt) => ({
        startTime: round(lt.startTime),
        duration: round(lt.duration),
        containers: Array.from(lt.attribution || []).map((a) => ({
          name: a.name,
          containerType: a.containerType,
          containerSrc: a.containerSrc,
          containerId: a.containerId,
          containerName: a.containerName
        }))
      }));

    return {
      loafCount: overlappingLoAFs.length,
      renderingSubPhases: {
        scriptAndEventWorkDuration: round(totalWorkDuration),
        renderDuration: round(totalRenderDuration),
        preLayoutDuration: round(totalPreLayoutDuration),
        styleAndLayoutDuration: round(totalStyleAndLayoutDuration),
        blockingDuration: round(totalBlockingDuration)
      },
      scripts,
      culpritScript: scripts[0] || null,
      longTasks: overlappingLongTasks
    };
  }

  /**
   * Builds full phase and script attribution for an Event Timing entry cluster
   * sharing an `interactionId`.
   */
  function buildInteractionAttribution(interaction) {
    // Choose the longest event entry in the interaction group, and span the full window
    const longestEntry = interaction.entries.reduce(
      (max, curr) => (curr.duration > max.duration ? curr : max),
      interaction.entries[0]
    );

    const startTime = Math.min(...interaction.entries.map((e) => e.startTime));
    const endTime = Math.max(
      ...interaction.entries.map((e) => e.startTime + e.duration)
    );
    const processingStart = Math.min(
      ...interaction.entries.map((e) => e.processingStart)
    );
    const processingEnd = Math.max(
      ...interaction.entries.map((e) => e.processingEnd)
    );
    const duration = Math.max(longestEntry.duration, endTime - startTime);

    // Core Event Timing 3-Phase Breakdown:
    // 1. Input Delay: waiting on main thread before event handlers start running
    // 2. Processing Duration: time spent running event listeners for this interaction
    // 3. Presentation Delay: style recalculation, layout, paint, compositing to next frame
    const inputDelay = Math.max(0, processingStart - startTime);
    const processingDuration = Math.max(0, processingEnd - processingStart);
    const presentationDelay = Math.max(0, endTime - processingEnd);

    const phases = {
      inputDelay: round(inputDelay),
      processingDuration: round(processingDuration),
      presentationDelay: round(presentationDelay)
    };

    // Determine dominant bottleneck phase
    const dominantPhase = Object.entries(phases).reduce(
      (best, [name, val]) => (val > best.value ? { name, value: val } : best),
      { name: 'inputDelay', value: -1 }
    );

    const loafAttribution = attributeWithLoAF(startTime, endTime);

    return {
      interactionId: interaction.id,
      interactionType: longestEntry.name,
      duration: round(duration),
      rating: getINPRating(duration),
      startTime: round(startTime),
      nextPaintTime: round(endTime),
      interactionTarget: getTargetSelector(longestEntry.target),
      eventTypes: interaction.entries.map((e) => e.name),
      phases,
      dominantPhase: dominantPhase.name,
      renderingPhases: {
        inputDelay: phases.inputDelay,
        processingDuration: phases.processingDuration,
        presentationDelay: phases.presentationDelay,
        ...loafAttribution.renderingSubPhases
      },
      scripts: loafAttribution.scripts,
      culpritScript: loafAttribution.culpritScript,
      loafCount: loafAttribution.loafCount,
      longTasks: loafAttribution.longTasks,
      pageUrl: window.location.href,
      timestamp: new Date().toISOString()
    };
  }

  /**
   * Computes the p98 interaction (high-percentile approximation used by the official INP spec:
   * worst interaction for <50 interactions, or 98th percentile interaction for >=50).
   */
  function computeCurrentINP() {
    const list = Array.from(interactionsById.values());
    if (list.length === 0) return null;
    list.sort((a, b) => b.duration - a.duration);
    const index = Math.min(list.length - 1, Math.floor(list.length / 50));
    const chosen = list[index];
    return buildInteractionAttribution(chosen);
  }

  function round(num) {
    return Math.round((Number(num) || 0) * 100) / 100;
  }

  /**
   * Processes Event Timing entries (`event` and `first-input`).
   */
  function handleEventEntries(entries) {
    let updated = false;
    for (const entry of entries) {
      if (!entry.interactionId) continue;

      let existing = interactionsById.get(entry.interactionId);
      if (!existing) {
        interactionCount += 1;
        existing = {
          id: entry.interactionId,
          duration: entry.duration,
          entries: [entry]
        };
        interactionsById.set(entry.interactionId, existing);
      } else {
        existing.entries.push(entry);
        if (entry.duration > existing.duration) {
          existing.duration = entry.duration;
        }
      }

      // Keep bounded list of tracked interactions
      if (interactionsById.size > CONFIG.maxInteractionsTracked) {
        let minId = null;
        let minDur = Infinity;
        for (const [id, item] of interactionsById.entries()) {
          if (item.duration < minDur) {
            minDur = item.duration;
            minId = id;
          }
        }
        if (minId !== null) interactionsById.delete(minId);
      }

      updated = true;
    }

    if (updated) {
      // Wait until after the next frame / LoAF entry is emitted before finalizing attribution
      requestAnimationFrame(() => {
        setTimeout(() => {
          const inpReport = computeCurrentINP();
          if (inpReport) {
            state.currentINP = inpReport;
            state.interactions = Array.from(interactionsById.values())
              .sort((a, b) => b.duration - a.duration)
              .map(buildInteractionAttribution);

            updateHUD(inpReport);
            window.dispatchEvent(
              new CustomEvent('dailygrind:inp-update', { detail: inpReport })
            );
          }
        }, 0);
      });
    }
  }

  /**
   * Sends the attributed INP telemetry report to the RUM collector via sendBeacon / fetch.
   */
  function flushINPReport(reason) {
    const inpReport = computeCurrentINP();
    if (!inpReport) return null;

    state.currentINP = inpReport;
    const signature = `${inpReport.interactionId}:${inpReport.duration}`;
    if (signature === lastReportedINPId && reason !== 'manual') {
      return inpReport;
    }
    lastReportedINPId = signature;

    const payload = {
      metric: 'INP',
      value: inpReport.duration,
      rating: inpReport.rating,
      navigationType:
        performance.getEntriesByType?.('navigation')?.[0]?.type || 'navigate',
      interactionCount,
      reason,
      attribution: {
        interactionId: inpReport.interactionId,
        interactionType: inpReport.interactionType,
        interactionTarget: inpReport.interactionTarget,
        startTime: inpReport.startTime,
        nextPaintTime: inpReport.nextPaintTime,
        dominantPhase: inpReport.dominantPhase,
        phases: inpReport.phases,
        renderingPhases: inpReport.renderingPhases,
        culpritScript: inpReport.culpritScript,
        scripts: inpReport.scripts,
        loafCount: inpReport.loafCount,
        longTasks: inpReport.longTasks
      },
      pageUrl: inpReport.pageUrl,
      timestamp: inpReport.timestamp
    };

    state.beaconsSent.push(payload);

    try {
      const body = JSON.stringify(payload);
      if (navigator.sendBeacon) {
        const blob = new Blob([body], { type: 'application/json' });
        navigator.sendBeacon(CONFIG.endpoint, blob);
      } else if (window.fetch) {
        window.fetch(CONFIG.endpoint, {
          method: 'POST',
          body,
          headers: { 'Content-Type': 'application/json' },
          keepalive: true
        }).catch(() => {});
      }
    } catch (_) {
      // Ignore network errors in offline/static environments
    }

    return payload;
  }

  /**
   * Updates the on-page real-time INP Telemetry HUD.
   */
  function updateHUD(report) {
    const valueEl = document.getElementById('inp-hud-value');
    const badgeEl = document.getElementById('inp-hud-badge');
    const targetEl = document.getElementById('inp-hud-target');
    const dominantEl = document.getElementById('inp-hud-dominant');
    const inputDelayEl = document.getElementById('inp-phase-input');
    const procDurEl = document.getElementById('inp-phase-processing');
    const presDelayEl = document.getElementById('inp-phase-presentation');
    const styleLayoutEl = document.getElementById('inp-phase-style-layout');
    const scriptsContainer = document.getElementById('inp-hud-scripts');

    if (!valueEl) return;

    valueEl.textContent = `${report.duration} ms (${report.interactionType})`;
    if (badgeEl) {
      badgeEl.textContent = report.rating.toUpperCase();
      badgeEl.className = `inp-badge ${report.rating}`;
    }
    if (targetEl) targetEl.textContent = report.interactionTarget;
    if (dominantEl) dominantEl.textContent = report.dominantPhase;
    if (inputDelayEl) inputDelayEl.textContent = `${report.phases.inputDelay}ms`;
    if (procDurEl) procDurEl.textContent = `${report.phases.processingDuration}ms`;
    if (presDelayEl) presDelayEl.textContent = `${report.phases.presentationDelay}ms`;
    if (styleLayoutEl) {
      styleLayoutEl.textContent = `${report.renderingPhases.styleAndLayoutDuration}ms`;
    }

    if (scriptsContainer) {
      scriptsContainer.innerHTML = '';
      if (report.scripts.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'inp-script-item';
        empty.textContent = 'No Long Animation Frame (>50ms) scripts recorded';
        scriptsContainer.appendChild(empty);
      } else {
        for (const s of report.scripts.slice(0, 3)) {
          const item = document.createElement('div');
          item.className = 'inp-script-item';
          const shortUrl = s.sourceURL ? s.sourceURL.split('/').pop() || s.sourceURL : 'inline';
          item.textContent = `${s.sourceFunctionName} @ ${shortUrl} (${s.duration}ms, layout: ${s.forcedStyleAndLayoutDuration}ms, invoker: ${s.invoker})`;
          scriptsContainer.appendChild(item);
        }
      }
    }
  }

  // 1. Register Long Animation Frames (LoAF) observer for script & rendering phase attribution
  if (typeof PerformanceObserver !== 'undefined') {
    const supported = PerformanceObserver.supportedEntryTypes || [];

    if (supported.includes('long-animation-frame')) {
      try {
        const loafObserver = new PerformanceObserver((list) => {
          for (const entry of list.getEntries()) {
            loafEntries.push(entry);
            if (loafEntries.length > CONFIG.maxLoAFBuffer) {
              loafEntries.shift();
            }
          }
        });
        loafObserver.observe({ type: 'long-animation-frame', buffered: true });
      } catch (_) {}
    }

    // 2. Register Long Tasks observer as fallback for script container attribution
    if (supported.includes('longtask')) {
      try {
        const ltObserver = new PerformanceObserver((list) => {
          for (const entry of list.getEntries()) {
            longTaskEntries.push(entry);
            if (longTaskEntries.length > CONFIG.maxLoAFBuffer) {
              longTaskEntries.shift();
            }
          }
        });
        ltObserver.observe({ type: 'longtask', buffered: true });
      } catch (_) {}
    }

    // 3. Register Event Timing observer (`event` and `first-input`) for INP tracking
    if (supported.includes('event')) {
      try {
        const eventObserver = new PerformanceObserver((list) => {
          handleEventEntries(list.getEntries());
        });
        eventObserver.observe({
          type: 'event',
          durationThreshold: CONFIG.slowThresholdMs,
          buffered: true
        });
      } catch (_) {}
    }

    if (supported.includes('first-input')) {
      try {
        const firstInputObserver = new PerformanceObserver((list) => {
          handleEventEntries(list.getEntries());
        });
        firstInputObserver.observe({ type: 'first-input', buffered: true });
      } catch (_) {}
    }
  }

  // Flush final INP telemetry when the page is hidden or unloaded
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') {
      flushINPReport('visibilitychange');
    }
  });
  window.addEventListener('pagehide', () => {
    flushINPReport('pagehide');
  });

  // Expose public inspection & diagnostic API on window
  window.DailyGrindINPMonitor = {
    config: CONFIG,
    state,
    getINPReport: computeCurrentINP,
    getAllInteractions: () =>
      Array.from(interactionsById.values())
        .sort((a, b) => b.duration - a.duration)
        .map(buildInteractionAttribution),
    attributeInteraction: buildInteractionAttribution,
    attributeWithLoAF,
    flush: () => flushINPReport('manual')
  };
})();

